mapper.update:
UPDATE twin_exp_record
SET review_status = #{reviewStatus},
    reviewed_by = #{reviewedBy},
    reviewed_at = NOW()

        , review_note = #{reviewNote}

WHERE id = #{id}

mapper.select:
SELECT anomaly_types, COUNT(*) AS cnt
FROM twin_exp_record
WHERE anomaly_flag = 1
  AND create_time >= #{startDate}
  AND create_time  <=  #{endDate}
GROUP BY anomaly_types
